// Interface lubrication element. Unified problems
#ifndef OOMPH_UPPER_INTERFACE_LUBRICATION_HEADER
#define OOMPH_UPPER_INTERFACE_LUBRICATION_HEADER

// Config header generated by autoconfig
#ifdef HAVE_CONFIG_H
#include <oomph-lib-config.h>
#endif

// oomph-lib headers
#include "../fluid_interface/specific_node_update_interface_elements.h"

namespace oomph {
//==================================================================
/// Generic vapour lubrication equations implemented
/// independently of the dimension and then specialised using
/// the generic mechanisms introduce in the FluidInterfaceElements
//=================================================================
class UpperInterfaceLubricationElement : public FluidInterfaceElement {
private:
  /// Pointer to ratio of vapour viscosity to liquid viscosity
  double *Vapour_Viscosity_Ratio_pt;

  /// Pointer to Dim-less Hamaker number
  double *Hamaker_pt;

  /// Pointer to Dim-less Mean Free Path
  double *Mean_Free_Path_pt;

  /// Pointer to GKE factor Delta Tau P function
  void (*GKE_Tau_P_fct_pt)(const double &Kn, double &result);

  /// Pointer to GKE factor Delta Tau C function
  void (*GKE_Tau_C_fct_pt)(const double &Kn, double &result);

  /// Pointer to GKE factor Delta Phi P function
  void (*GKE_Phi_P_fct_pt)(const double &Kn, double &result);

  /// Pointer to GKE factor Delta Phi C function
  void (*GKE_Phi_C_fct_pt)(const double &Kn, double &result);

protected:
  /// Index at which the Vapour Pressure is stored at the
  /// nodes
  Vector<unsigned> Pv_index;

  /// Index at which the Arc length is stored at the
  /// nodes
  Vector<unsigned> Al_index;

  /// Default value of the physical constants
  static double Default_Physical_Constant_Value;

  bool above_bath_flag;

  /// Get the arc length
  double interpolated_Al(const Vector<double> &s);

  /// Overload the Helper function to calculate the residuals and
  /// jacobian entries. This particular function ensures that the
  /// additional entries are calculated inside the integration loop
  void add_additional_residual_contributions_interface(
      Vector<double> &residuals, DenseMatrix<double> &jacobian,
      const unsigned &flag, const Shape &psif, const DShape &dpsifds,
      const DShape &dpsifdS, const DShape &dpsifdS_div, const Vector<double> &s,
      const Vector<double> &interpolated_x,
      const Vector<double> &interpolated_n, const double &W, const double &J);

  /// Function to calculate GKE Tau P factor
  void get_GKE_Tau_P(const double &Kn, double &result) {
    // If the function pointer is zero return 1
    if (GKE_Tau_P_fct_pt == 0) {
      result = 1.0;
    }
    // Otherwise call the function
    else {
      (*GKE_Tau_P_fct_pt)(Kn, result);
    }
  }

  /// Function to calculate GKE Tau C factor
  void get_GKE_Tau_C(const double &Kn, double &result) {
    // If the function pointer is zero return 1
    if (GKE_Tau_C_fct_pt == 0) {
      result = 1.0;
    }
    // Otherwise call the function
    else {
      (*GKE_Tau_C_fct_pt)(Kn, result);
    }
  }

  /// Function to calculate GKE Phi P factor
  void get_GKE_Phi_P(const double &Kn, double &result) {
    // If the function pointer is zero return 1
    if (GKE_Phi_P_fct_pt == 0) {
      result = 1.0;
    }
    // Otherwise call the function
    else {
      (*GKE_Phi_P_fct_pt)(Kn, result);
    }
  }

  /// Function to calculate GKE Phi C factor
  void get_GKE_Phi_C(const double &Kn, double &result) {
    // If the function pointer is zero return 1
    if (GKE_Phi_C_fct_pt == 0) {
      result = 1.0;
    }
    // Otherwise call the function
    else {
      (*GKE_Phi_C_fct_pt)(Kn, result);
    }
  }

  /// Function to calculate impact surface
  virtual void get_lower_surface(const unsigned &intpt, Vector<double> &x_out,
                                 Vector<double> &n_out, Vector<double> &u_out, Vector<double> &dx_dt_out) {
    // Return a flat surface. Virtual to overwrite for the external element

    const unsigned el_dim = this->dim();
    Vector<double> s(el_dim);

    // Get the value of the local coordiantes at the integration point
    for (unsigned i = 0; i < el_dim; i++) {
      s[i] = this->integral_pt()->knot(intpt, i);
    }

    x_out[0] = this->interpolated_x(s, 0);
    x_out[1] = 0.0;
    n_out[0] = 0.0;
    n_out[1] = 1.0;
    u_out[0] = 0.0;
    u_out[1] = 0.0;
    dx_dt_out[0]=0.0;
    dx_dt_out[1]=0.0;

  }

  /// Add the element's contribution to its residuals vector,
  /// jacobian matrix and mass matrix
  void fill_in_contribution_to_jacobian_and_mass_matrix(
      Vector<double> &residuals, DenseMatrix<double> &jacobian,
      DenseMatrix<double> &mass_matrix) {
    // Add the contribution to the jacobian
    this->fill_in_contribution_to_jacobian(residuals, jacobian);
    // No mass matrix terms, but should probably do kinematic bit here
  }

public:
  /// Constructor that passes the bulk element and face index down
  /// to the underlying
  UpperInterfaceLubricationElement() : FluidInterfaceElement() {
    // Initialise the values
    Vapour_Viscosity_Ratio_pt = &Default_Physical_Constant_Value;
    Hamaker_pt = &Default_Physical_Constant_Value;
    Mean_Free_Path_pt = &Default_Physical_Constant_Value;
    above_bath_flag = true;

    GKE_Tau_P_fct_pt = 0;
    GKE_Tau_C_fct_pt = 0;
    GKE_Phi_P_fct_pt = 0;
    GKE_Phi_C_fct_pt = 0;
  }

  /// Destructor should not delete anything
  ~UpperInterfaceLubricationElement() {}

  // Access function for the GKE Tau P factor pointer
  void (*&gke_Tau_P_fct_pt())(const double &Kn, double &result) {
    return GKE_Tau_P_fct_pt;
  }

  // Access function for the GKE Tau C factor pointer
  void (*&gke_Tau_C_fct_pt())(const double &Kn, double &result) {
    return GKE_Tau_C_fct_pt;
  }

  // Access function for the GKE Phi P factor pointer
  void (*&gke_Phi_P_fct_pt())(const double &Kn, double &result) {
    return GKE_Phi_P_fct_pt;
  }

  // Access function for the GKE Phi C factor pointer
  void (*&gke_Phi_C_fct_pt())(const double &Kn, double &result) {
    return GKE_Phi_C_fct_pt;
  }

  // Set the pv_index
  inline void set_pv_index(const Vector<unsigned> &pv_index) {
    this->Pv_index = pv_index;
  }

  // Set the al_index
  inline void set_al_index(const Vector<unsigned> &al_index) {
    this->Al_index = al_index;
  }

  bool above_bath() const { return above_bath_flag; }

  void set_above_bath(bool above_bath_in) { above_bath_flag = above_bath_in; }

  /// Return the vapour viscosity ratio
  double vapour_viscosity_ratio() { return *Vapour_Viscosity_Ratio_pt; }

  /// Return the vapour viscosity ratio
  double vapour_viscosity_ratio() const { return *Vapour_Viscosity_Ratio_pt; }

  /// Return the Dim-less Hamaker number
  double hamaker() { return *Hamaker_pt; }

  /// Return the Dim-less Hamaker number
  double hamaker() const { return *Hamaker_pt; }

  /// Return the Dim-less Mean Free Path
  double mean_free_path() { return *Mean_Free_Path_pt; }

  /// Access function for pointer to the vapour viscosity ratio
  double *&vapour_viscosity_ratio_pt() { return Vapour_Viscosity_Ratio_pt; }

  /// Access function for pointer to the Dim-less Hamaker number
  double *&hamaker_pt() { return Hamaker_pt; }

  /// Access function for pointer to the Dim-less mean free path
  double *&mean_free_path_pt() { return Mean_Free_Path_pt; }

  // fix the vapour pressure
  void fix_vapour_pressure(const unsigned &pv_dof, const double &pv_value) {
    this->node_pt(pv_dof)->pin(this->Pv_index[pv_dof]);
    this->node_pt(pv_dof)->set_value(this->Pv_index[pv_dof], pv_value);
  }

  // fix the vapour pressure
  void unpin_vapour_pressure(const unsigned &pv_dof) {
    this->node_pt(pv_dof)->unpin(this->Pv_index[pv_dof]);
  }

  // set the vapour pressure (e.g for initial condition)
  void set_vapour_pressure(const unsigned &pv_dof, const double &pv_value) {
    this->node_pt(pv_dof)->set_value(this->Pv_index[pv_dof], pv_value);
  }

  // fix the arc length
  void fix_arc_length(const unsigned &al_dof, const double &al_value) {
    this->node_pt(al_dof)->pin(this->Al_index[al_dof]);
    this->node_pt(al_dof)->set_value(this->Al_index[al_dof], al_value);
  }

  /// Function to calculate min thickness
  virtual double min_thickness() {
    double min_value = 1000.0;

    const unsigned el_dim = this->dim();
    Vector<double> s(el_dim);
    // Loop over points on surface element
    // Set the value of n_intpt
    unsigned n_intpt = integral_pt()->nweight();

    // Loop over the integration points
    for (unsigned ipt = 0; ipt < n_intpt; ipt++) {
      // Get the value of the local coordiantes at the integration point
      for (unsigned i = 0; i < el_dim; i++) {
        s[i] = this->integral_pt()->knot(ipt, i);
      }
      unsigned n_dim = this->nodal_dimension();
      // Check if z is less than lowest previously found
      Vector<double> x(n_dim);
      this->interpolated_x(s, x);
      Vector<double> n(n_dim);
      this->outer_unit_normal(ipt, n);
      Vector<double> x_lower(2, 0.0);
      Vector<double> n_lower(2, 0.0); // Unused here
      Vector<double> u_lower(2, 0.0); // Unused here
      Vector<double> dx_dt_lower(2, 0.0); // Unused here
      get_lower_surface(ipt, x_lower, n_lower, u_lower,dx_dt_lower);
      double h = (x_lower[0] - x[0]) * n[0] + (x_lower[1] - x[1]) * n[1];
      if (h < min_value) {
        min_value = h;
      }
    }

    return min_value;
  }

  /// Function to calculate min drop base height
  virtual double min_drop_base() {
    double min_value = 1000.0;

    const unsigned el_dim = this->dim();
    Vector<double> s(el_dim);
    // Loop over points on surface element
    // Set the value of n_intpt
    unsigned n_intpt = integral_pt()->nweight();

    // Loop over the integration points
    for (unsigned ipt = 0; ipt < n_intpt; ipt++) {
      // Get the value of the local coordiantes at the integration point
      for (unsigned i = 0; i < el_dim; i++) {
        s[i] = this->integral_pt()->knot(ipt, i);
      }
      unsigned n_dim = this->nodal_dimension();
      // Check if z is less than lowest previously found
      Vector<double> x(n_dim);
      this->interpolated_x(s, x);
      if (x[1] < min_value) {
        min_value = x[1];
      }
    }

    return min_value;
  }

  void to_lower_surface(const Vector<double> &s, Vector<double> &x_out,
                        Vector<double> &u_out, double &pv_out,
                        Vector<double> &grad_pv_out) const {
    // NEED: dpsifdS, psif
    // Find out how many nodes there are
    // HACKY, IF EVER DO 2D or 3D, this will need replacing
    unsigned n_node = this->nnode();
    const unsigned n_dim = this->node_pt(0)->ndim();
    Vector<unsigned> u_index = this->U_index_interface;

    // Find out the number of surface coordinates
    const unsigned el_dim = this->dim();
    // We have el_dim local surface coordinates
    DShape dpsifds(n_node, el_dim);
    Shape psif(n_node);
    this->dshape_local(s, psif, dpsifds);

    DShape dpsifdS(n_node, n_dim);

    // Define and zero the tangent Vectors and local velocities
    DenseMatrix<double> interpolated_t(el_dim, n_dim, 0.0);

    Vector<double> interpolated_dw_ds(n_dim, 0.0);

    // Loop over the shape functions
    for (unsigned l = 0; l < n_node; l++) {
      // Loop over directional components
      for (unsigned i = 0; i < n_dim; i++) {
        interpolated_dw_ds[i] += this->dnodal_position_dt(l, i) * dpsifds(l, 0);
        // Calculate the tangent vectors
        for (unsigned j = 0; j < el_dim; j++) {
          interpolated_t(j, i) += this->nodal_position(l, i) * dpsifds(l, j);
        }
      }
    }

    // Initially the same as the 2D case
    const unsigned n_shape = psif.nindex1();

    // Calculate the only entry of the surface
    // metric tensor (square length of the tangent vector)
    double a11 = interpolated_t(0, 0) * interpolated_t(0, 0) +
                 interpolated_t(0, 1) * interpolated_t(0, 1);

    // Now set the derivative terms of the shape functions
    for (unsigned l = 0; l < n_shape; l++) {
      for (unsigned i = 0; i < n_dim; i++) {
        dpsifdS(l, i) = dpsifds(l, 0) * interpolated_t(0, i) / a11;
      }
    }

    for (unsigned l = 0; l < n_node; l++) {
      const double psi = psif(l);
      const double Pv_ = this->nodal_value(l, this->Pv_index[l]);
      pv_out += Pv_ * psi;
      for (unsigned j = 0; j < n_dim; j++) {
        const double u_ = this->nodal_value(l, u_index[j]);
        const double x_ = this->nodal_position(l, j);
        x_out[j] += x_ * psi;
        u_out[j] += u_ * psi;
        grad_pv_out[j] += Pv_ * dpsifdS(l, j);
      }
    }
   

  }

  /// Get the Vapour Pressure
  double interpolated_Pv(const Vector<double> &s) const;

  /// Overload the output function in .cc file
  void output(std::ostream &outfile) { FiniteElement::output(outfile); }

  /// Overload the output function
  void output(std::ostream &outfile, const unsigned &n_plot);

  /// Overload the C-style output function
  void output(FILE *file_pt) { FiniteElement::output(file_pt); }

  /// C-style Output function
  void output(FILE *file_pt, const unsigned &n_plot) {
    FiniteElement::output(file_pt, n_plot);
  }

}; // End of Vapour Class

/// =============================================================================
/// This is the policy class for the Interface Lubrication equations which
/// require one additional value for the surface concentration
//=============================================================================
template <>
class FluidInterfaceAdditionalValues<UpperInterfaceLubricationElement> {
public:
  FluidInterfaceAdditionalValues<UpperInterfaceLubricationElement>() {}

  inline unsigned nadditional_values(const unsigned &n) { return 2; }

  inline void
  setup_equation_indices(UpperInterfaceLubricationElement *const &element_pt,
                         const unsigned &id) {
    const unsigned n_node = element_pt->nnode();
    Vector<unsigned> pv_index(n_node);
    Vector<unsigned> al_index(n_node);
    for (unsigned n = 0; n < n_node; n++) {
      pv_index[n] = dynamic_cast<BoundaryNodeBase *>(element_pt->node_pt(n))
                        ->index_of_first_value_assigned_by_face_element(id);
      al_index[n] = dynamic_cast<BoundaryNodeBase *>(element_pt->node_pt(n))
                        ->index_of_first_value_assigned_by_face_element(id) +
                    1;
    }

    element_pt->set_pv_index(pv_index);
    element_pt->set_al_index(al_index);
  }
};

/// Specialise to the Axisymmetric geometry
template <class ELEMENT>
class ElasticAxisymmetricUpperInterfaceLubricationElement
    : public ElasticUpdateFluidInterfaceElement<
          UpperInterfaceLubricationElement, AxisymmetricDerivatives, ELEMENT> {
public:
  ElasticAxisymmetricUpperInterfaceLubricationElement(
      FiniteElement *const &element_pt, const int &face_index)
      : ElasticUpdateFluidInterfaceElement<UpperInterfaceLubricationElement,
                                           AxisymmetricDerivatives, ELEMENT>(
            element_pt, face_index) {}
};

// Define the bounding element type for the axisymmetric surface
template <class ELEMENT>
class BoundingElementType<ElasticUpdateFluidInterfaceElement<
    UpperInterfaceLubricationElement, AxisymmetricDerivatives, ELEMENT>>
    : public ElasticPointFluidInterfaceBoundingElement<ELEMENT> {
public:
  BoundingElementType<ElasticUpdateFluidInterfaceElement<
      UpperInterfaceLubricationElement, AxisymmetricDerivatives, ELEMENT>>()
      : ElasticPointFluidInterfaceBoundingElement<ELEMENT>() {}
};

} // namespace oomph

#endif
